const x = $input.first()?.json || {};

const action = String(
  x.action ||
  x.audit_action ||
  'operation'
).toLowerCase();

const intent = String(x.intent || '').toLowerCase();

const entityMap = {
  invoice: 'Invoice',
  customer: 'Customer',
  order: 'Order',
  ticket: 'Ticket',
  approval: 'Approval',
  report: 'Report',
  product: 'Product'
};

const entityType = String(
  x.entity_type ||
  entityMap[intent] ||
  x.result_type?.replace('_view', '') ||
  'Business'
);

// --------------------------------------------------
// Entity ID
// --------------------------------------------------

let entityId = String(
  x.entity_id ||
  x.invoice_id ||
  x.customer_id ||
  x.order_id ||
  x.ticket_id ||
  x.approval_id ||
  ''
).trim();

// إذا وصلت قيمة expression كنص حرفي، تجاهلها
const literalExpression =
  entityId.includes('$json.') ||
  entityId.includes('{') ||
  entityId.includes('||');

if (literalExpression) {
  entityId = '';
}

// إذا لم يوجد ID صحيح، استخرجه من تفاصيل العملية
if (!entityId) {
  const sourceText = String(
    x.details ||
    x.reply ||
    x.result ||
    ''
  );

  const idFieldMap = {
    Invoice: 'invoice_id',
    Customer: 'customer_id',
    Order: 'order_id',
    Ticket: 'ticket_id',
    Approval: 'approval_id',
    Product: 'product_id'
  };

  const field = idFieldMap[entityType];

  if (field) {
    const regex = new RegExp(
      `${field}:\\s*([^|\\n<]+)`,
      'gi'
    );

    const ids = [];
    let match;

    while ((match = regex.exec(sourceText)) !== null) {
      const id = String(match[1]).trim();

      if (id && !ids.includes(id)) {
        ids.push(id);
      }
    }

    entityId = ids.join(', ');
  }
}

// --------------------------------------------------
// Status
// --------------------------------------------------

const status = String(
  x.status ||
  x.audit_status ||
  'Completed'
);

// --------------------------------------------------
// Details
// --------------------------------------------------

let details =
  x.details ||
  x.reply ||
  x.result ||
  '';

if (typeof details !== 'string') {
  details = JSON.stringify(details);
}

if (!details) {
  details = `Action: ${action}`;
}

if (details.length > 45000) {
  details = details.slice(0, 45000);
}

// --------------------------------------------------
// Final Audit Record
// --------------------------------------------------

return [{
  json: {
    log_id: `LOG-${Date.now()}`,
    timestamp: new Date().toISOString(),
    user_id: String(x.user_id || 'system'),
    user_name: String(x.user_name || ''),
    user_role: String(x.role || x.user_role || ''),
    action,
    entity_type: entityType,
    entity_id: entityId,
    status,
    details
  }
}];

const input = $('When Executed by Another Workflow').first()?.json || {};
const audit = $('Prepare Audit Entry').first()?.json || {};

return [{
  json: {
    ...input,
    audit_logged: true,
    audit_log_id: audit.log_id || '',
    audit_timestamp: audit.timestamp || '',
    reply: input.reply || 'تم تسجيل العملية في سجل التدقيق.'
  }
}];
